'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tiers={bronze:'青铜',silver:'白银',gold:'黄金',diamond:'钻石',king:'王者'};
let tasks=[],runnables=[],implementations=[],view='catalog',tier='all',query='',selected=new Set(),results=[];
const stateKey='jab-planner-v1';
// Local storage and imported files are data, never trusted verdicts.
const isObject=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
function savedPlan(){try{const p=JSON.parse(localStorage.getItem(stateKey)||'{}');return isObject(p)?p:{}}catch{return {}}}
function validateResult(r){
 if(r?.schema_version==='engineering-1.0')return validateEngineeringResult(r);
 const known=runnables.find(t=>t.id===r?.task_id&&t.status==='runnable');
 const statuses=['build_failed','compile_timeout','run_timeout','verification_failed','passed','compile_output_limit','run_output_limit'];
 if(!isObject(r)||r.schema_version!=='1.0'||!known||!/^R[0-9]{2}$/.test(r.task_id))throw Error('不是支持的单次验收结果：需要已知 R 系列任务与 schema_version 1.0');
 if(typeof r.task_version!=='string'||!r.task_version||r.task_version!==known.environment?.task_version)throw Error('任务版本不匹配；仅支持当前目录中的明确版本');
 const process=p=>isObject(p)&&Array.isArray(p.argv)&&p.argv.every(a=>typeof a==='string')&&Number.isInteger(p.exit_code)&&typeof p.timed_out==='boolean'&&typeof p.output_limited==='boolean'&&Number.isInteger(p.output_limit_bytes)&&p.output_limit_bytes>0&&Number.isFinite(p.duration_seconds)&&p.duration_seconds>=0&&typeof p.stdout==='string'&&typeof p.stderr==='string';
 if(!statuses.includes(r.status)||typeof r.passed!=='boolean'||!Number.isInteger(r.expected_checks)||r.expected_checks<8||!Array.isArray(r.checks)||!r.checks.every(c=>isObject(c)&&typeof c.name==='string'&&typeof c.passed==='boolean'&&typeof c.detail==='string')||typeof r.timestamp_utc!=='string'||!Number.isFinite(Date.parse(r.timestamp_utc))||typeof r.patch_sha256!=='string'||! /^[a-f0-9]{64}$/.test(r.patch_sha256)||!isObject(r.environment)||!['java','python','platform'].every(k=>typeof r.environment[k]==='string')||!['category','tier','security'].every(k=>typeof r[k]==='string')||!process(r.compile)||!(r.run===null||process(r.run)))throw Error('验收结果字段或状态不符合支持的格式');
 if(Array.isArray(known.acceptance)&&(r.expected_checks!==known.acceptance.length||r.checks.some(c=>!known.acceptance.includes(c.name))||new Set(r.checks.map(c=>c.name)).size!==r.checks.length))throw Error('检查名称或数量与当前任务不匹配');
 if(r.passed!==(r.status==='passed'))throw Error('passed 与 status 不一致');
 if(r.passed&&(!r.run||r.run.exit_code!==0||r.run.timed_out||r.run.output_limited||r.compile.exit_code!==0||r.compile.timed_out||r.compile.output_limited||r.checks.length!==r.expected_checks||!r.checks.every(c=>c.passed)||new Set(r.checks.map(c=>c.name)).size!==r.expected_checks))throw Error('成功状态与逐项证据不一致');
 return r;
}

function validateEngineeringResult(r){
 const known=implementations.find(x=>x.implementation_id===r.implementation_id&&x.id===r.design_id);
 const hash=v=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v);
 if(!known||!['passed','failed','timeout','output_limit','invalid_report'].includes(r.status)||typeof r.passed!=='boolean'||r.passed!==(r.status==='passed')||!hash(r.submission_sha256)||!hash(r.manifest_sha256)||(known.manifest_sha256&&r.manifest_sha256!==known.manifest_sha256)||!Number.isFinite(r.elapsed_seconds)||r.elapsed_seconds<0||!Number.isInteger(r.exit_code)||typeof r.timestamp_utc!=='string'||!Number.isFinite(Date.parse(r.timestamp_utc))||!isObject(r.candidate_files)||!Object.values(r.candidate_files).every(hash))throw Error('工程切片结果标识、状态或证据格式无效');
 if(r.passed&&(r.exit_code!==0||!isObject(r.report)))throw Error('工程切片成功状态与执行结果不一致');
 return r;
}

const list=a=>`<ul>${(Array.isArray(a)?a:(a&&typeof a==='object'?Object.entries(a).flatMap(([k,v])=>Array.isArray(v)?v.map(x=>k+'：'+(typeof x==='string'?x:JSON.stringify(x))):[k+'：'+String(v)]):a?[String(a)]:[])).map(x=>`<li>${esc(typeof x==='string'?x:x.criterion||x.description||JSON.stringify(x))}</li>`).join('')}</ul>`;
function renderBrief(b){if(typeof b==='string')return `<p style="white-space:pre-line;line-height:1.9">${esc(b)}</p>`;if(!isObject(b))return '';return `<p class="sub">${esc(b.context)}</p><p style="line-height:1.9">${esc(b.mission)}</p><h3>执行约束</h3>${list(b.constraints)}<h3>完整场景所需材料</h3>${list(b.inputPackagePlanned)}`;}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));({catalog:renderCatalog,planner:renderPlanner,results:renderResults,protocol:renderProtocol,roadmap:renderRoadmap}[view])()}
function card(t){const impl=implementations.find(x=>x.id===t.id);return `<article class="card"><div class="cardtop"><span class="tier ${esc(t.tier)}">${esc(tiers[t.tier]||'机制预实验')} · 暂定</span><span class="id">${esc(t.id)}</span></div><h3>${esc(t.title)}</h3><p>${esc(t.summary)}</p><div class="cardbottom"><span>${t.status==='runnable'?'● 可执行 · 非隔离沙箱':(impl?'◐ 原设计 + 可运行切片':'○ 设计稿 · 尚未实现')}</span><button data-detail="${esc(t.id)}">查看任务 ↗</button></div></article>`}
function renderCatalog(){const filtered=[...runnables,...tasks].filter(t=>(tier==='all'||t.tier===tier)&&(!query||JSON.stringify(t).toLowerCase().includes(query.toLowerCase())));$('#content').innerHTML=`<div class="sectionhead"><div><h2>任务实验室</h2><p class="sub">业务边界、跨模块约束与独立验收，让难度来自真实复杂性。</p></div><span class="small">${filtered.length} 个任务</span></div><div class="toolbar"><div class="tiers"><button data-tier="all" class="${tier==='all'?'active':''}">全部</button>${Object.entries(tiers).map(([k,v])=>`<button data-tier="${k}" class="${tier===k?'active':''}">${v}</button>`).join('')}</div><input id="search" aria-label="搜索任务" placeholder="搜索任务、能力或场景…" value="${esc(query)}"></div><div class="grid">${filtered.map(card).join('')||'<p class="empty">没有匹配的任务。试试其他关键词。</p>'}</div><div class="notice">状态说明：25 个分级场景是完整设计，工程切片只覆盖其中声明的部分；R 系列是独立机制预实验。难度尚未经多模型实测校准，不能据此声称达到任何模型段位。</div>`;$('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;renderCatalog();$('#search').focus();$('#search').setSelectionRange(pos,pos)};document.querySelectorAll('[data-tier]').forEach(b=>b.onclick=()=>{tier=b.dataset.tier;renderCatalog()});bindDetails()}
function bindDetails(){document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail))}
function detail(id){const t=[...runnables,...tasks].find(t=>t.id===id);if(!t)return;const taskImpls=implementations.filter(x=>x.id===id);const impl=taskImpls[0];$('#detailContent').innerHTML=`<div class="detailmeta"><span class="tier ${esc(t.tier)}">${esc(tiers[t.tier]||'机制预实验')}</span><span class="id">${esc(t.id)} / ${esc(t.status)}</span></div><h2>${esc(t.title)}</h2><p class="sub">${esc(t.summary)}</p><div class="notice">${t.status==='runnable'?'可执行机制验证，不是生产服务或安全隔离的模型评测。':'这是完整场景设计，不代表所有要求均已实现。下方若有工程切片，只能在其限定范围内评测；没有模型实测成绩。'}</div><h3>任务背景与目标</h3>${renderBrief(t.brief)}${taskImpls.map(x=>`<div class="panel"><h3>可运行工程变体 · ${esc(x.implementation_id)}</h3><a class="secondary" style="display:inline-block;text-decoration:none" href="packages/${encodeURIComponent(x.implementation_id)}.zip" download>下载候选任务包 ↓</a><p class="sub">${esc(x.scope)}</p><pre>${esc(x.command)}</pre><p class="small">代码路径：${esc(x.path)} · 公开开发集，不是隐藏验收或安全沙箱。</p></div>`).join('')}<h3>交付物</h3>${list(t.deliverables)}<h3>验收标准</h3>${list(t.acceptance)}<h3>风险与容易漏掉的边界</h3>${list(t.risks)}<h3>评分维度</h3>${(t.rubric||[]).map(r=>`<div class="rubric"><span>${esc(r.dimension)}<br><small>${esc(r.evidence)}</small></span><b>${esc(r.weight)}%</b></div>`).join('')}<h3>难度依据</h3><p class="sub">${esc(t.difficultyRationale)}</p>${t.command?`<h3>本地验证命令</h3><pre>${esc(t.command)}</pre>`:''}<h3>环境与验证计划</h3><pre>${esc(JSON.stringify(t.environment,null,2))}</pre><div class="actions"><button class="primary" id="addPlan">加入实验草案</button><button class="secondary" id="exportTask">导出任务 JSON</button></div>`;$('#addPlan').onclick=()=>{selected.add(id);$('#detail').close();view='planner';render()};$('#exportTask').onclick=()=>download(`${id}.json`,t);$('#detail').showModal()}
function renderPlanner(){const saved=savedPlan();$('#content').innerHTML=`<h2>设计对照实验</h2><p class="sub">一次只改变一个因素。导出配置交给执行器，不在网页中运行不可信代码。</p><div class="panel"><div class="fields"><label>实验名称<input id="experiment" value="${esc(saved.name||'新 Skill 配对实验')}"></label><label>比较对象<select id="track"><option value="skill">Skill / 工作流消融</option><option value="model">固定工作流的模型对比</option></select></label><label>对照组标识<input id="control" value="${esc(saved.control||'baseline-no-skill')}"></label><label>实验组标识<input id="treatment" value="${esc(saved.treatment||'workflow-v2')}"></label><label>固定模型 / 模型版本<input id="model" value="${esc(saved.model||'请填写精确版本')}"></label><label>每题重复次数<input id="repeats" type="number" min="1" max="100" value="${esc(saved.repeats||3)}"></label><label>每次时间预算（秒）<input id="budget" type="number" min="1" max="86400" value="${esc(saved.budget||1800)}"></label><label>随机种子<input id="seed" type="number" value="${esc(saved.seed??42)}"></label></div><h3>选择任务 <span class="small">${selected.size} 已选</span></h3><div class="tiers">${[...runnables,...tasks].map(t=>`<label class="tag"><input type="checkbox" data-select="${esc(t.id)}" ${selected.has(t.id)?'checked':''}> ${esc(t.id)} ${esc(t.title)}${implementations.some(x=>x.id===t.id)?' · 工程切片':''}</label>`).join('')}</div><div class="notice">设计稿可以进入规划，但不能执行或计分。公开开发集不能保证模型未见过；严格比较应使用隔离运行、固定预算和保留测试集。费用为空表示未知，不是免费。</div><div class="actions"><button class="primary" id="exportPlan">导出实验计划</button><button class="secondary" id="savePlan">保存到此浏览器</button></div><p id="planStatus" role="status"></p></div>`;$('#track').value=saved.track||'skill';document.querySelectorAll('[data-select]').forEach(c=>c.onchange=()=>{c.checked?selected.add(c.dataset.select):selected.delete(c.dataset.select)});function config(){const repeats=Number($('#repeats').value),budget=Number($('#budget').value);if(!selected.size)throw Error('请至少选择一个任务。');if(!Number.isInteger(repeats)||repeats<1||repeats>100||!Number.isFinite(budget)||budget<1||budget>86400)throw Error('重复次数或预算超出允许范围。');const seed=Number($('#seed').value);if(!Number.isSafeInteger(seed))throw Error('随机种子必须是安全整数。');return {schema_version:'0.1',name:$('#experiment').value,track:$('#track').value,control:$('#control').value,treatment:$('#treatment').value,model:$('#model').value,repeats,budget,seed,tasks:[...selected].map(id=>({id,status:implementations.some(x=>x.id===id)?'runnable_slice':[...runnables,...tasks].find(t=>t.id===id).status,implementation_id:implementations.find(x=>x.id===id)?.implementation_id||null,manifest_sha256:implementations.find(x=>x.id===id)?.manifest_sha256||null})),dataset_version:'0.2-public-dev',network_policy:'off_except_controlled_model_proxy',cost_usd:null,execution_status:'not_run',created_at:new Date().toISOString()}}$('#exportPlan').onclick=()=>{try{download('experiment-plan.json',config());$('#planStatus').textContent='已导出计划；没有启动任何模型或任务。'}catch(e){$('#planStatus').textContent=e.message}};$('#savePlan').onclick=()=>{try{localStorage.setItem(stateKey,JSON.stringify(config()));$('#planStatus').textContent='仅保存在此浏览器，可导出备份；不跨设备同步。'}catch(e){$('#planStatus').textContent=e.message}}}
function renderResults(){$('#content').innerHTML=`<h2>结果与证据</h2><p class="sub">没有模型实测，就不生成排行榜。导入本地验收结果，逐项查看证据。</p><div class="panel"><label class="primary" style="display:inline-block;cursor:pointer">导入结果 JSON<input id="resultFile" type="file" accept=".json,application/json" hidden multiple></label><p class="small">支持 R 系列单次结果与 engineering.py 工程切片结果；仅做字段与状态检查，不认证来源。文件只在浏览器内读取，不上传。每个文件上限 2 MB。</p><p id="resultError" role="status" class="error"></p><div id="resultList">${results.length?results.map((r,i)=>`<div class="resultrow"><div><b>${esc(r.task_id||r.implementation_id)}</b> <span class="tag">${esc(r.status)}</span><p class="small">任务版本 ${esc(r.task_version||r.manifest_sha256?.slice(0,12)||'未提供')} · ${esc(r.timestamp_utc||r.timestamp||r.created_at||'时间未提供')}</p></div><button class="secondary" data-result="${i}">查看原始证据</button></div>`).join(''):'<div class="empty"><h3>等第一份真实结果。</h3><p>这里不会预填模型名称、成功率或虚构排名。</p></div>'}</div></div><div class="notice">导入文件是用户提供的证据，未做密码学签名或来源认证。参考解与故障基线只是验收器自检，不是 AI 模型能力分数；不要跨题目版本直接比较。</div>`;$('#resultFile').onchange=async e=>{for(const f of e.target.files){try{if(f.size>2*1024*1024)throw Error('文件超过 2 MB');const r=JSON.parse(await f.text());validateResult(r);results.push(r)}catch(err){$('#resultError').textContent=`${f.name}: ${err.message}`;return}}renderResults()};document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const r=results[Number(b.dataset.result)];$('#detailContent').innerHTML=`<h2>原始验收证据</h2><pre>${esc(JSON.stringify(r,null,2))}</pre>`;$('#detail').showModal()})}
function renderProtocol(){$('#content').innerHTML=`<h2>评测协议</h2><p class="sub">先排除“题目有问题”和“测量不公平”，再解释分数。</p><div class="panel">${[['01','任务门禁','参考解全部通过、原始缺陷失败、多个有针对性的错误修复被检出。验收必须来自业务口径，不能由被测模型自行定义。'],['02','公平对照','模型榜固定工具、提示词、预算与工作流；系统榜披露完整系统。Skill 实验固定模型和任务，做配对 A/B，并保留失败尝试。'],['03','独立验收','严肃测评需要隔离 agent 与 verifier，补丁应用到全新基线后重测。当前 Python/Java 内核只是可信代码的本地功能验证，不是安全沙箱。'],['04','证据链','固定题目版本、来源提交、环境版本、补丁哈希与原始日志。区分编译失败、业务失败、超时和基础设施失败。'],['05','报告边界','主指标为严格业务成功率。费用、时间、回归与维护性分列；报告题数、重复次数与不确定性。公开开发集始终存在污染风险。']].map(([n,t,p])=>`<div class="step"><strong>${n}</strong><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div><h3>参考项目 · 设计借鉴，不表示复制其题目</h3><div class="panel"><ul><li><a href="https://www.swebench.com/multilingual" target="_blank" rel="noopener">SWE-bench Multilingual</a>：真实仓库缺陷与补丁验收。</li><li><a href="https://github.com/multi-swe-bench/multi-swe-bench" target="_blank" rel="noopener">Multi-SWE-bench</a>：Java 等多语言构建与评测。</li><li><a href="https://github.com/harbor-framework/harbor" target="_blank" rel="noopener">Harbor</a>：隔离执行、任务规范与轨迹记录。</li><li><a href="https://github.com/scaleapi/SWE-bench_Pro-os/blob/main/v2/README.md" target="_blank" rel="noopener">SWE-bench Pro V2</a>：独立验收与防止环境篡改。</li></ul></div>`}
function renderRoadmap(){$('#content').innerHTML=`<h2>建设进度</h2><p class="sub">把已验证的成果与仍需实现的工作放在同一张清单上。</p><div class="panel">${[['01','当前交付 · 开发预览','五档 25 个完整设计与限定范围的工程切片；R01–R03 机制任务；本地执行入口和结果证据。切片并不等于完整生产场景。'],['02','下一阶段 · 真实工程化','将设计稿逐题落为 Maven/Spring/数据库工程；补齐契约、回归和故障注入测试，锁定依赖与环境镜像。'],['03','隔离与接入','接入 Harbor 或独立执行器，隔离网络与文件系统、限制资源、采集模型与子 Agent 费用。公开开发集与保留测试集分离。'],['04','实测与校准','在明确模型、调用预算及权限后，执行配对预实验，排查天花板、地板和不稳定题。难度以证据校准，不凭题目长度命名。'],['05','持续发布','版本化扩充题族，发布变更日志与回归证据；历史成绩固定到具体任务版本，不追溯性改榜。']].map(([n,t,p])=>`<div class="step"><strong>${n}</strong><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div>`}
$('#closeDetail').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close()});document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});
Promise.all([fetch('tasks.json').then(r=>{if(!r.ok)throw Error('任务目录加载失败');return r.json()}),fetch('runnable.json').then(r=>r.ok?r.json():[]),fetch('implementations.json').then(r=>r.ok?r.json():[]).catch(()=>[])]).then(([t,r,i])=>{tasks=t;runnables=r;implementations=Array.isArray(i)?i:[];$('#total').textContent=String(tasks.length).padStart(2,'0');$('#runnable').textContent=String(r.length+implementations.length).padStart(2,'0');$('#repoLink').href='https://github.com/Wfyywj/java-agent-bench';$('#repoLink').textContent='GitHub 源码 ↗';try{const p=savedPlan();selected=new Set((Array.isArray(p.tasks)?p.tasks:[]).filter(isObject).map(x=>x.id).filter(id=>[...t,...r].some(x=>x.id===id)))}catch{}render()}).catch(e=>{$('#content').innerHTML=`<div class="notice error">${esc(e.message)}。请刷新后重试。</div>`});
